rules.pseudocode:
n = (int)pauseBars;
if (!LargeShapedBarAtLag(lag = n)) return false;
R = high[n] - low[n]; H = high[n];
for (j = 0; j < n; ++j)
  if (!(high[j] - low[j] < smallFraction * R && high[j] <= H + bandFraction * R && low[j] >= H - bandFraction * R)) return false;
return true;

for (k = minHoldBars + 1; k <= maxBars; ++k) {
  if (!LargeShapedBarAtLag(lag = k, bear shape)) continue;
  R = high[k] - low[k]; mid = low[k] + 0.5 * R; ext = low[k] - extFraction * R;
  if (any j in 1..k-1 with close[j] > mid || close[j] < ext) continue;
  if (close[0] > mid) return true;
}
return false;

if (!LargeShapedBarAtLag(lag = 1, minRangeAtr = 1.5, maxRangeAtr = inf, openFraction = 1/3, closeFraction = 1/3)) return false;
R = high[1] - low[1];
if (close[1] < highest(high, extremeLookback)[1] - nearAtr * atrVal[1]) return false;   // at or near the 20-bar high
return high[0] > high[1] && close[0] >= high[1] - closeZone * R;

for (b = 2; b <= maxBars; ++b) {
  if (!LargeShapedBarAtLag(lag = b, minRangeAtr = hugeAtr, maxRangeAtr = inf, openFraction = nearFraction, closeFraction = nearFraction)) continue;
  if (!(high[b] > highest(high, breakLookback)[b + 1])) continue;   // took out the X-bar high
  if (lowest(low, b)[0] < low[b]) continue;                         // invalidated: huge bar's far extreme taken out
  i = most recent j in 1..b-1 that is inside bar j+1 (high[j] < high[j+1] && low[j] > low[j+1]),
      with close[j] < open[j], high[j] - open[j] <= nearFraction * (high[j]-low[j]), close[j] - low[j] <= nearFraction * (high[j]-low[j]);
  if (!i found) continue;
  if (any j in 1..i-1 with close[j] > open[j]) continue;              // first green after the inside bar
  return close[0] > open[0];
}
return false;

n = (int)containedBars;   // bars 2..X, so X = n + 1 and bar 1 is at offset n + 1
m = n + 1; R = high[m] - low[m];
if (!(close[m] > open[m] && close[m] - open[m] > bodyFraction * R && R > minRangeAtr * atrVal[m])) return false;
for (j = 1; j <= n; ++j) if (!(high[j] <= high[m] && low[j] >= low[m])) return false;
return low[0] >= low[m] && close[0] > high[m];

// long as written: bear bar at offset W
midW = (high[W] + low[W]) / 2;
strong = el_lt(close[W], open[W]) && el_ge(open[W] - close[W], F * (high[W] - low[W])) && el_ge(high[W] - low[W], K * atrAt(W));
clean = true; for (i = 0; i < W; ++i) if (el_ge(high[i], midW)) clean = false;
long = strong && clean;

t = bar of highest(high, maxRun + maxPullback) in 1..; H = high[t];
run: s = t; while (s + 1 <= t + maxRun - 1 && el_gt(close[s + 1], open[s + 1])) s = s + 1;   // requires el_gt(close[t], open[t])
height = H - open[s];
breakaway = (s - t + 1 >= minRunBars) || el_ge(height, A * atr);
pb = t - 1; ok = pb >= minPullback && pb <= maxPullback;
for (i = 1; i < t; ++i) if (el_ge(high[i], H) || el_lt(low[i], H - f * height)) ok = false;
long = breakaway && ok && el_gt(close[0], H);

// long mirror; a > b >= 1 (bars ago)
sig1(a) = el_le(low[a], lowest(low, X)[a]) && no bar in 0..a-1 has el_lt(low[i], low[a]);
sig2(b) = a - b >= 1 && a - b <= X && el_ge(high[b], highest(high, X)[b]) && no bar in 0..b-1 has el_gt(high[i], high[b]);
zoneTop = low[b] + Y * (high[b] - low[b]);
first = no close in 1..b-1 inside [low[b], zoneTop];
long = sig1 && sig2 && first && el_le(close[0], zoneTop) && el_ge(close[0], low[b]);

// long mirror
top = highest(high, N)[1]; bot = lowest(low, N)[1]; mid = (top + bot) / 2;
long = el_lt(low[0], bot) && el_gt(high[0], mid) && el_ge(high[0] - low[0], minRangeAtr * atr);

primitives_to_inline.pseudocode:
r = high[lag] - low[lag];
a = atrVal[lag];                       // ATR series variable read at the bar's own offset
return r > minRangeAtr * a && r < maxRangeAtr * a
    && open[lag] - low[lag]   <= openFraction  * r
    && high[lag] - close[lag] <= closeFraction * r;
